<?php
namespace App\Controllers;
use App\Core\Database;
final class OrderController{public function index():void{$db=Database::db();$status=$_GET['status']??'';$sql="SELECT o.*,COUNT(i.id) items FROM orders o LEFT JOIN order_items i ON i.order_id=o.id";$args=[];if(in_array($status,['pending','paid','failed','refunded'],true)){$sql.=" WHERE o.status=?";$args[]=$status;}$sql.=" GROUP BY o.id ORDER BY o.id DESC";$s=$db->prepare($sql);$s->execute($args);$orders=$s->fetchAll();$selected=null;$items=[];if(!empty($_GET['id'])){$q=$db->prepare('SELECT * FROM orders WHERE id=?');$q->execute([(int)$_GET['id']]);$selected=$q->fetch();if($selected){$q=$db->prepare('SELECT i.*,p.title,p.preview_path,e.name event_name FROM order_items i JOIN photos p ON p.id=i.photo_id JOIN events e ON e.id=p.event_id WHERE i.order_id=?');$q->execute([$selected['id']]);$items=$q->fetchAll();}}admin_view('admin/orders',['orders'=>$orders,'selected'=>$selected,'items'=>$items,'pageTitle'=>'Pedidos','adminSection'=>'orders']);}public function status():never{verify_csrf();$status=$_POST['status']??'';if(in_array($status,['pending','paid','failed','refunded'],true))Database::db()->prepare("UPDATE orders SET status=?,paid_at=IF(?='paid',COALESCE(paid_at,NOW()),paid_at) WHERE id=?")->execute([$status,$status,(int)($_POST['id']??0)]);redirect('/admin/pedidos?id='.(int)($_POST['id']??0));}}

